package pipeline

import (
	"os"
	"path/filepath"
	"testing"
)

// TestHeaderStepAcceptsTheOldCLIName checks that a file written before the
// CLI was renamed from nano to nanostack is still the pipeline's own, so the
// first run after an upgrade rewrites it instead of skipping it as
// hand-written, and that a go:generate line running either name is caught.
func TestHeaderStepAcceptsTheOldCLIName(t *testing.T) {
	dir := t.TempDir()
	for name, header := range map[string]string{
		"new.go":  "// Code generated by nanostack gen wire from manifest.go. DO NOT EDIT.\n",
		"old.go":  "// Code generated by nano gen wire from manifest.go. DO NOT EDIT.\n",
		"old.md":  "<!-- Code generated by nano gen errors from errors.go. DO NOT EDIT. -->\n",
		"mock.go": "// Code generated by mockgen. DO NOT EDIT.\n",
	} {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(header+"package x\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	for name, want := range map[string]string{"new.go": "wire", "old.go": "wire", "old.md": "errors", "mock.go": ""} {
		if got := headerStep(filepath.Join(dir, name)); got != want {
			t.Errorf("headerStep(%s) = %q, want %q", name, got, want)
		}
	}
	for _, cmd := range []string{"go tool nanostack gen wire", "go tool nano gen wire", "go run ./cmd/nano gen"} {
		if !nanoGenPattern.MatchString(cmd) {
			t.Errorf("nanoGenPattern does not match %q", cmd)
		}
	}
}
